    }

    function _run(uint256 deposit, uint256 amount) internal {
        deposit = bound(deposit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(deposit >= amount);
        vm.assume(address(this).balance >= deposit);
        try c.Deposit{value: deposit}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 ethBefore = address(c).balance;
        uint256 minSum;
        try c.MinSum() returns (uint256 __r) { minSum = __r; } catch { return; }
        vm.assume(balBefore >= minSum + amount);
        bool reverted;
        try c.Collect(amount) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted
            && c.balances(address(this)) == balBefore - amount
            && ethBefore - address(c).balance == amount);
